    {
        RemoveCommandListener("say",      OnPlayerSay, HookMode.Pre);
        RemoveCommandListener("say_team", OnPlayerSay, HookMode.Pre);
    }

    private string ResolveJsonPath(string configValue, string fileName)
    {
        if (!string.IsNullOrEmpty(configValue) && File.Exists(configValue))
            return configValue;

        // CS# BasePlugin.ModulePath returns the plugin's DLL full path (reliable across loaders)
        string? dllPath = null;
        try { dllPath = ModulePath; } catch { }

        var dllDir = !string.IsNullOrEmpty(dllPath) ? Path.GetDirectoryName(dllPath) ?? "" : "";
        // Sibling plugin folder pattern: plugins/SeedCommand/ -> plugins/WeaponPaints/data/<file>
        if (!string.IsNullOrEmpty(dllDir))
        {
            var candidate = Path.GetFullPath(Path.Combine(dllDir, "..", "WeaponPaints", "data", fileName));
            if (File.Exists(candidate)) return candidate;
        }

        // Final fallback: relative to game's working directory
        var cwd = Directory.GetCurrentDirectory();
        var fallback = Path.GetFullPath(Path.Combine(cwd, "..", "..", "csgo", "addons", "counterstrikesharp", "plugins", "WeaponPaints", "data", fileName));
        return fallback;
    }

    private string ResolveSkinsJsonPath()  => ResolveJsonPath(Config.SkinsJsonPath,  "skins_en.json");
    private string ResolveGlovesJsonPath() => ResolveJsonPath(Config.GlovesJsonPath, "gloves_en.json");

    private void LoadSkinData()
    {
        var path = ResolveSkinsJsonPath();
        try
        {
            using var doc = JsonDocument.Parse(File.ReadAllText(path));
            foreach (var entry in doc.RootElement.EnumerateArray())
            {
                if (!entry.TryGetProperty("weapon_name", out var wName)) continue;
                if (!entry.TryGetProperty("paint",       out var paintEl)) continue;
                if (!entry.TryGetProperty("paint_name",  out var nameEl)) continue;
                var weapon = wName.GetString() ?? ""; if (string.IsNullOrEmpty(weapon)) continue;
                int paintId;
                if (paintEl.ValueKind == JsonValueKind.String)
                {
                    if (!int.TryParse(paintEl.GetString(), out paintId)) continue;
                }
                else if (paintEl.ValueKind == JsonValueKind.Number) paintId = paintEl.GetInt32();
                else continue;
                var paintName = nameEl.GetString() ?? "?";
                if (!_paintsByWeapon.TryGetValue(weapon, out var list))
                {
                    list = new List<(int, string)>();
                    _paintsByWeapon[weapon] = list;
                }
                list.Add((paintId, paintName));
            }
            foreach (var key in _paintsByWeapon.Keys.ToList())
                _paintsByWeapon[key] = _paintsByWeapon[key].OrderBy(x => x.name).ToList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[SeedCommand] FAILED loading skins from {path}: {ex.Message}");
        }
    }

    private void LoadGloveData()
    {
        var path = ResolveGlovesJsonPath();
        try
        {
            using var doc = JsonDocument.Parse(File.ReadAllText(path));
            foreach (var entry in doc.RootElement.EnumerateArray())
            {
                if (!entry.TryGetProperty("weapon_defindex", out var defEl)) continue;
                if (!entry.TryGetProperty("paint",           out var paintEl)) continue;
                if (!entry.TryGetProperty("paint_name",      out var nameEl)) continue;
                int defindex = defEl.ValueKind == JsonValueKind.Number ? defEl.GetInt32() : 0;
                int paintId;
                if (paintEl.ValueKind == JsonValueKind.String)
                {
                    if (!int.TryParse(paintEl.GetString(), out paintId)) continue;
                }
                else if (paintEl.ValueKind == JsonValueKind.Number) paintId = paintEl.GetInt32();
                else continue;
                var paintName = nameEl.GetString() ?? "?";
                _allGloves.Add((defindex, paintId, paintName));
            }
            _allGloves.Sort((a, b) => string.Compare(a.name, b.name, StringComparison.OrdinalIgnoreCase));
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[SeedCommand] FAILED loading gloves from {path}: {ex.Message}");
        }
    }

    // ============================================================
    // Chat router — intercepts !k, !ws, !gloves before WeaponPaints
    // ============================================================
    private HookResult OnPlayerSay(CCSPlayerController? player, CommandInfo info)
    {
        if (player == null || !player.IsValid || player.IsBot) return HookResult.Continue;
        if (info.ArgCount < 2) return HookResult.Continue;
        string text = info.GetArg(1).Trim().ToLowerInvariant();
        if (string.IsNullOrEmpty(text)) return HookResult.Continue;
        string firstWord = text.Split(' ', '\t')[0];
        int slot = player.Slot;

        switch (firstWord)
        {
            case "!k":
            case "!knife":
                Server.NextFrame(() => OpenKnifeTypeMenu(slot));
                return HookResult.Stop;
            case "!ws":
                Server.NextFrame(() => OpenHeldWeaponSkinMenu(slot));
                return HookResult.Stop;
            case "!gloves":
                Server.NextFrame(() => OpenGlovesMenu(slot));
                return HookResult.Stop;
            case "!sticker":
            case "!stickers":
                Server.NextFrame(() => OpenStickerMenu(slot));
                return HookResult.Stop;
        }

        return HookResult.Continue;
    }

    // ============================================================
    // !k → knife type menu → skin menu → apply
    // ============================================================
    private void OpenKnifeTypeMenu(int slot)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        var menu = CreateMenu("Pick a knife");
        if (menu == null) { p.PrintToChat(" \x07[Seed]\x01 Menu creation failed."); return; }
        dynamic menuDyn = menu;

        foreach (var (display, weaponName, defindex) in KnifeTypes)
        {
            string capW = weaponName; int capD = defindex; string capDisplay = display;
            Action<CCSPlayerController, object> handler = (caller, opt) =>
            {
                if (caller == null || !caller.IsValid) return;
                OnKnifeTypePicked(caller.Slot, capW, capD, capDisplay);
            };
            menuDyn.AddMenuOption(display, handler);
        }
        AppendCreditOption(menuDyn);
        menuDyn.Open(p);
    }

    private void OnKnifeTypePicked(int slot, string weaponName, int defindex, string display)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        string steamId = p.SteamID.ToString();
        int team = p.TeamNum;

        Task.Run(async () =>
        {
            try
            {
                await using var conn = new MySqlConnection(ConnString);
                await conn.OpenAsync();
                await using var cmd = conn.CreateCommand();
                cmd.CommandText = @"INSERT INTO wp_player_knife (steamid, weapon_team, knife)
                                    VALUES (@sid, @team, @knife)
                                    ON DUPLICATE KEY UPDATE knife = @knife";
                cmd.Parameters.AddWithValue("@sid",   steamId);
                cmd.Parameters.AddWithValue("@team",  team);
                cmd.Parameters.AddWithValue("@knife", weaponName);
                await cmd.ExecuteNonQueryAsync();
            }
            catch { }

            Server.NextFrame(() =>
            {
                var pp = Utilities.GetPlayerFromSlot(slot);
                if (pp == null || !pp.IsValid) return;
                pp.PrintToChat($" \x06[Seed]\x01 Knife: \x06{display}\x01 — pick a skin:");
                ShowSkinMenuForWeapon(slot, weaponName, defindex, display);
            });
        });
    }

    // ============================================================
    // !ws → skin menu for held weapon → apply
    // ============================================================
    private void OpenHeldWeaponSkinMenu(int slot)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        var pawn = p.PlayerPawn.Value;
        var active = pawn?.WeaponServices?.ActiveWeapon.Value;
        if (active == null || !active.IsValid) { p.PrintToChat(" \x07[Seed]\x01 Hold a weapon first."); return; }

        int defindex = active.AttributeManager.Item.ItemDefinitionIndex;
        string weaponName = active.DesignerName;
        // strip "_weapon_" prefix variants — DesignerName is e.g. "weapon_ak47"
        string display = weaponName.Replace("weapon_", "").Replace("knife_", "Knife ").Replace("_", " ");

        ShowSkinMenuForWeapon(slot, weaponName, defindex, display);
    }

    private void ShowSkinMenuForWeapon(int slot, string weaponName, int defindex, string displayName)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        if (!_paintsByWeapon.TryGetValue(weaponName, out var paints) || paints.Count == 0)
        {
            p.PrintToChat($" \x07[Seed]\x01 No paints found for {weaponName}");
            return;
        }
        var menu = CreateMenu($"Skins for {displayName}");
        if (menu == null) return;
        dynamic menuDyn = menu;

        foreach (var (paintId, paintName) in paints)
        {
            string fullName = DecoratePaintName(paintId, paintName);
            string label = fullName;
            int pipeIdx = label.LastIndexOf('|');
            if (pipeIdx > 0 && pipeIdx + 1 < label.Length) label = label.Substring(pipeIdx + 1).Trim();
            if (label.Contains("Doppler")) label = $"{label} [{paintId}]";

            int capPaint = paintId; string capName = fullName; string capWeapon = weaponName; int capDef = defindex;
            Action<CCSPlayerController, object> h = (c, o) =>
            {
                if (c == null || !c.IsValid) return;
                ApplySkin(c.Slot, capDef, capPaint, capName, capWeapon);
            };
            menuDyn.AddMenuOption(label, h);
        }
        AppendCreditOption(menuDyn);
        menuDyn.Open(p);
    }

    private static string DecoratePaintName(int paintId, string paintName)
        => DopplerPhaseTag.TryGetValue(paintId, out var tag) ? $"{paintName} ({tag})" : paintName;

    // ============================================================
    // !gloves → flat glove menu → apply
    // ============================================================
    private void OpenGlovesMenu(int slot)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        if (_allGloves.Count == 0) { p.PrintToChat(" \x07[Seed]\x01 No glove data loaded."); return; }
        var menu = CreateMenu("Pick gloves");
        if (menu == null) return;
        dynamic menuDyn = menu;

        foreach (var (defindex, paint, name) in _allGloves)
        {
            string label = name;
            int pipeIdx = label.LastIndexOf('|');
            if (pipeIdx > 0 && pipeIdx + 1 < label.Length) label = label.Substring(pipeIdx + 1).Trim();
            int capDef = defindex; int capPaint = paint; string capName = name;
            Action<CCSPlayerController, object> h = (c, o) =>
            {
                if (c == null || !c.IsValid) return;
                ApplyGloves(c.Slot, capDef, capPaint, capName);
            };
            menuDyn.AddMenuOption(label, h);
        }
        AppendCreditOption(menuDyn);
        menuDyn.Open(p);
    }

    private void ApplyGloves(int slot, int defindex, int paintId, string paintName)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        string steamId = p.SteamID.ToString();
        int team = p.TeamNum;

        Task.Run(async () =>
        {
            string reply;
            try
            {
                await using var conn = new MySqlConnection(ConnString);
                await conn.OpenAsync();
                // wp_player_gloves selects which glove TYPE is equipped
                await using var c1 = conn.CreateCommand();
                c1.CommandText = @"INSERT INTO wp_player_gloves (steamid, weapon_team, weapon_defindex)
                                   VALUES (@sid, @team, @def)
                                   ON DUPLICATE KEY UPDATE weapon_defindex = @def";
                c1.Parameters.AddWithValue("@sid", steamId);
                c1.Parameters.AddWithValue("@team", team);
                c1.Parameters.AddWithValue("@def", defindex);
                await c1.ExecuteNonQueryAsync();

                // wp_player_skins holds the paint for that glove defindex
                await using var c2 = conn.CreateCommand();
                c2.CommandText = @"INSERT INTO wp_player_skins (steamid, weapon_team, weapon_defindex, weapon_paint_id, weapon_wear, weapon_seed)
                                   VALUES (@sid, @team, @def, @paint, 0.000001, 0)
                                   ON DUPLICATE KEY UPDATE weapon_paint_id = @paint";
                c2.Parameters.AddWithValue("@sid", steamId);
                c2.Parameters.AddWithValue("@team", team);
                c2.Parameters.AddWithValue("@def", defindex);
                c2.Parameters.AddWithValue("@paint", paintId);
                await c2.ExecuteNonQueryAsync();
                reply = $" \x06[Seed]\x01 Gloves: \x06{paintName}\x01. Next round for visual change.";
            }
            catch (Exception ex) { reply = $" \x07[Seed]\x01 SQL: {ex.Message}"; }

            Server.NextFrame(() =>
            {
                var pp = Utilities.GetPlayerFromSlot(slot);
                if (pp != null && pp.IsValid) { pp.PrintToChat(reply); TriggerWpRefresh(pp); }
            });
        });
    }

    // ============================================================
    // !sticker → menu of high-value stickers → slot picker → apply
    // ============================================================
    private void OpenStickerMenu(int slot)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        var (active, _) = GetHeldWeapon(p);
        if (active == null) { p.PrintToChat(" \x07[Seed]\x01 Hold a weapon first."); return; }

        int defindex = active.AttributeManager.Item.ItemDefinitionIndex;
        string weaponClassname = active.DesignerName;

        var menu = CreateMenu("Pick a sticker");
        if (menu == null) return;
        dynamic menuDyn = menu;

        foreach (var (id, display) in HighValueStickers)
        {
            int capId = id; string capDisplay = display;
            int capDef = defindex; string capCls = weaponClassname;
            Action<CCSPlayerController, object> h = (c, o) =>
            {
                if (c == null || !c.IsValid) return;
                OpenStickerSlotMenu(c.Slot, capDef, capCls, capId, capDisplay);
            };
            menuDyn.AddMenuOption(display, h);
        }
        AppendCreditOption(menuDyn);
        menuDyn.Open(p);
    }

    private void OpenStickerSlotMenu(int slot, int defindex, string weaponClassname, int stickerId, string stickerName)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        var menu = CreateMenu($"{stickerName} — pick a slot");
        if (menu == null) return;
        dynamic menuDyn = menu;

        for (int i = 0; i < 5; i++)
        {
            int capSlotIdx = i;
            int capDef = defindex; string capCls = weaponClassname; int capStickerId = stickerId; string capStickerName = stickerName;
            Action<CCSPlayerController, object> h = (c, o) =>
            {
                if (c == null || !c.IsValid) return;
                ApplySticker(c.Slot, capDef, capCls, capSlotIdx, capStickerId, capStickerName);
            };
            menuDyn.AddMenuOption($"Slot {capSlotIdx + 1}", h);
        }
        // Also offer "All 5 slots" as a convenience
        int allDef = defindex; string allCls = weaponClassname; int allId = stickerId; string allName = stickerName;
        Action<CCSPlayerController, object> applyAll = (c, o) =>
        {
            if (c == null || !c.IsValid) return;
            for (int i = 0; i < 5; i++) ApplySticker(c.Slot, allDef, allCls, i, allId, allName, suppressRefresh: i < 4);
        };
        menuDyn.AddMenuOption("ALL 5 slots", applyAll);
        menuDyn.Open(p);
    }

    private void ApplySticker(int slot, int defindex, string weaponClassname, int stickerSlot, int stickerId, string stickerName, bool suppressRefresh = false)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        string steamId = p.SteamID.ToString();
        int team = p.TeamNum;
        string column = $"weapon_sticker_{stickerSlot}";
        // WP sticker DB format: id;schema;OffsetX;OffsetY;Wear;Scale;Rotation
        string stickerData = $"{stickerId};0;0;0;0;1;0";

        Task.Run(async () =>
        {
            string reply;
            try
            {
                await using var conn = new MySqlConnection(ConnString);
                await conn.OpenAsync();
                // Column name is hardcoded (whitelist via stickerSlot 0-4 only) so SQL injection safe
                await using var cmd = conn.CreateCommand();
                cmd.CommandText = $@"
                    INSERT INTO wp_player_skins (steamid, weapon_team, weapon_defindex, weapon_paint_id, weapon_wear, weapon_seed, {column})
                    VALUES (@sid, @team, @def, 0, 0.000001, 0, @data)
                    ON DUPLICATE KEY UPDATE {column} = @data";
                cmd.Parameters.AddWithValue("@sid", steamId);
                cmd.Parameters.AddWithValue("@team", team);
                cmd.Parameters.AddWithValue("@def", defindex);
                cmd.Parameters.AddWithValue("@data", stickerData);
                await cmd.ExecuteNonQueryAsync();
                reply = $" \x06[Seed]\x01 Sticker slot {stickerSlot + 1}: \x06{stickerName}\x01 applied.";
            }
            catch (Exception ex) { reply = $" \x07[Seed]\x01 SQL: {ex.Message}"; }

            Server.NextFrame(() =>
            {
                var pp = Utilities.GetPlayerFromSlot(slot);
                if (pp == null || !pp.IsValid) return;
                pp.PrintToChat(reply);
                if (!suppressRefresh) TriggerWpRefresh(pp);
            });
        });
    }

    // ============================================================
    // Apply a skin to a non-glove weapon, then refresh
    // ============================================================
    private void ApplySkin(int slot, int defindex, int paintId, string paintName, string weaponClassname)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;
        string steamId = p.SteamID.ToString();
        int team = p.TeamNum;

        Task.Run(async () =>
        {
            string reply; int seed = 0;
            try
            {
                await using var conn = new MySqlConnection(ConnString);
                await conn.OpenAsync();
                await using var cmd = conn.CreateCommand();
                cmd.CommandText = @"INSERT INTO wp_player_skins (steamid, weapon_team, weapon_defindex, weapon_paint_id, weapon_wear, weapon_seed)
                                    VALUES (@sid, @team, @def, @paint, 0.000001, 0)
                                    ON DUPLICATE KEY UPDATE weapon_paint_id = @paint";
                cmd.Parameters.AddWithValue("@sid",   steamId);
                cmd.Parameters.AddWithValue("@team",  team);
                cmd.Parameters.AddWithValue("@def",   defindex);
                cmd.Parameters.AddWithValue("@paint", paintId);
                await cmd.ExecuteNonQueryAsync();

                await using var read = conn.CreateCommand();
                read.CommandText = "SELECT weapon_seed FROM wp_player_skins WHERE steamid=@sid AND weapon_team=@team AND weapon_defindex=@def";
                read.Parameters.AddWithValue("@sid", steamId); read.Parameters.AddWithValue("@team", team); read.Parameters.AddWithValue("@def", defindex);
                seed = Convert.ToInt32(await read.ExecuteScalarAsync() ?? 0);

                reply = $" \x06[Seed]\x01 \x06{paintName}\x01 (paint {paintId}, seed {seed}, FN).";
            }
            catch (Exception ex) { reply = $" \x07[Seed]\x01 SQL: {ex.Message}"; }

            Server.NextFrame(() =>
            {
                var pp = Utilities.GetPlayerFromSlot(slot);
                if (pp == null || !pp.IsValid) return;
                pp.PrintToChat(reply);
                // Directly invoke WeaponPaints' refresh via reflection - bypasses the chat trigger
                TriggerWpRefresh(pp);
            });
        });
    }

    private void ForceWeaponRefresh(int slot, string weaponClassname)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return;

        // Strategy 1: Full respawn — most reliable, WeaponPaints reloads loadout from DB on spawn.
        // Use this for practice/bot servers where position loss is acceptable.
        if (Config.ForceRespawnOnSkinChange)
        {
            try { p.Respawn(); return; } catch { /* fall through to drop+give */ }
        }

        // Strategy 2: Drop + give (less disruptive but relies on WP's cache being fresh)
        var pawn = p.PlayerPawn.Value;
        if (pawn == null) return;
        try
        {
            var weapons = pawn.WeaponServices?.MyWeapons;
            if (weapons != null)
            {
                foreach (var handle in weapons)
                {
                    var w = handle?.Value;
                    if (w == null || !w.IsValid) continue;
                    if (w.DesignerName == weaponClassname || w.DesignerName.StartsWith(weaponClassname))
                        w.Remove();
                }
            }
            p.ExecuteClientCommandFromServer($"give {weaponClassname}");
        }
        catch { }
    }

    // ============================================================
    // !seed <n> — manual seed override on held weapon
    // ============================================================
    [ConsoleCommand("css_seed", "Set paint seed on held weapon")]
    [CommandHelper(minArgs: 1, usage: "<seed_number>", whoCanExecute: CommandUsage.CLIENT_ONLY)]
    public void OnSeed(CCSPlayerController? player, CommandInfo command)
    {
        if (player == null || !player.IsValid || player.IsBot) return;
        if (!int.TryParse(command.GetArg(1), out int seed) || seed < 0 || seed > 1000000)
        { command.ReplyToCommand(" \x07[Seed]\x01 Usage: !seed <0 - 1000000>"); return; }
        ApplyHeldWeaponField(player, "weapon_seed", seed, $"seed=\x06{seed}\x01");
    }

    // ============================================================
    // !bestseed — apply best community-known seed for held weapon's current paint
    // ============================================================
    [ConsoleCommand("css_bestseed", "Apply the best community seed for the held weapon's current paint")]
    [CommandHelper(whoCanExecute: CommandUsage.CLIENT_ONLY)]
    public void OnBestSeed(CCSPlayerController? player, CommandInfo command)
    {
        if (player == null || !player.IsValid || player.IsBot) return;
        var (active, _) = GetHeldWeapon(player);
        if (active == null) { command.ReplyToCommand(" \x07[Seed]\x01 Hold a weapon first."); return; }
        int defindex = active.AttributeManager.Item.ItemDefinitionIndex;
        int team = player.TeamNum; string steamId = player.SteamID.ToString(); int slot = player.Slot;

        Task.Run(async () =>
        {
            string reply;
            try
            {
                await using var conn = new MySqlConnection(ConnString);
                await conn.OpenAsync();
                await using var cmd = conn.CreateCommand();
                cmd.CommandText = @"
                    UPDATE wp_player_skins s
                    JOIN best_seeds bs ON bs.weapon_defindex = s.weapon_defindex AND bs.weapon_paint_id = s.weapon_paint_id
                    SET s.weapon_seed = bs.best_seed
                    WHERE s.steamid = @sid AND s.weapon_team = @team AND s.weapon_defindex = @def";
                cmd.Parameters.AddWithValue("@sid", steamId);
                cmd.Parameters.AddWithValue("@team", team);
                cmd.Parameters.AddWithValue("@def", defindex);
                int rows = await cmd.ExecuteNonQueryAsync();
                reply = rows > 0
                    ? " \x06[Seed]\x01 Best seed applied. Refreshing..."
                    : " \x07[Seed]\x01 No best-seed entry for this paint (skin uses default seed).";
            }
            catch (Exception ex) { reply = $" \x07[Seed]\x01 SQL: {ex.Message}"; }

            Server.NextFrame(() =>
            {
                var p = Utilities.GetPlayerFromSlot(slot);
                if (p != null && p.IsValid)
                {
                    p.PrintToChat(reply);
                    TriggerWpRefresh(p);
                }
            });
        });
    }

