    // !wear <float> — set wear/float of held weapon
    // ============================================================
    [ConsoleCommand("css_wear", "Set wear (float) of held weapon. 0.000001=Factory New, 0.5=Battle-Scarred")]
    [ConsoleCommand("css_float", "Alias of css_wear")]
    [CommandHelper(minArgs: 1, usage: "<float 0.0-1.0>", whoCanExecute: CommandUsage.CLIENT_ONLY)]
    public void OnWear(CCSPlayerController? player, CommandInfo command)
    {
        if (player == null || !player.IsValid || player.IsBot) return;
        if (!float.TryParse(command.GetArg(1), NumberStyles.Float, CultureInfo.InvariantCulture, out float wear) || wear < 0f || wear > 1f)
        { command.ReplyToCommand(" \x07[Seed]\x01 Usage: !wear <0.0 - 1.0>"); return; }
        // CS2's actual minimum wear is 0.000001 — clamp upward so the row is accepted
        if (wear <= 0f) wear = 0.000001f;
        ApplyHeldWeaponField(player, "weapon_wear", wear, $"wear=\x06{wear:F4}\x01 ({WearTier(wear)})");
    }

