    // ============================================================
    // StatTrak kill counter — increment on player death
    // ============================================================
    [GameEventHandler]
    public HookResult OnPlayerDeath(EventPlayerDeath @event, GameEventInfo info)
    {
        var killer = @event.Attacker;
        var victim = @event.Userid;
        if (killer == null || !killer.IsValid || killer.IsBot) return HookResult.Continue;
        // Skip suicides and team-kills only when victim == killer
        if (victim != null && killer.SteamID == victim.SteamID) return HookResult.Continue;

        var pawn = killer.PlayerPawn.Value;
        var activeWeapon = pawn?.WeaponServices?.ActiveWeapon.Value;
        if (activeWeapon == null || !activeWeapon.IsValid) return HookResult.Continue;

        ushort defindex = activeWeapon.AttributeManager.Item.ItemDefinitionIndex;
        int team = killer.TeamNum;
        string steamId = killer.SteamID.ToString();

        Task.Run(async () =>
        {
            try
            {
                await using var conn = new MySqlConnection(ConnString);
                await conn.OpenAsync();
                await using var cmd = conn.CreateCommand();
                // Only increment if this row has StatTrak enabled
                cmd.CommandText = @"
                    UPDATE wp_player_skins
                    SET weapon_stattrak_count = weapon_stattrak_count + 1
                    WHERE steamid = @sid
                      AND weapon_team = @team
                      AND weapon_defindex = @def
                      AND weapon_stattrak = 1";
                cmd.Parameters.AddWithValue("@sid", steamId);
                cmd.Parameters.AddWithValue("@team", team);
                cmd.Parameters.AddWithValue("@def", (int)defindex);
                await cmd.ExecuteNonQueryAsync();
            }
            catch { /* silent — don't spam chat on every kill */ }
        });

        return HookResult.Continue;
    }

    private static string WearTier(float w)
        => w < 0.07f ? "Factory New"
         : w < 0.15f ? "Minimal Wear"
         : w < 0.38f ? "Field-Tested"
         : w < 0.45f ? "Well-Worn"
         : "Battle-Scarred";

    // ============================================================
    // Shared: update a single column on held weapon's row + refresh
    // ============================================================
    private void ApplyHeldWeaponField(CCSPlayerController player, string column, object value, string userVisible)
    {
        var (active, classname) = GetHeldWeapon(player);
        if (active == null) { player.PrintToChat(" \x07[Seed]\x01 Hold a weapon first."); return; }
        ushort defindex = active.AttributeManager.Item.ItemDefinitionIndex;
        int team = player.TeamNum; string steamId = player.SteamID.ToString(); int slot = player.Slot;

        Task.Run(async () =>
        {
            string reply;
            try
            {
                await using var conn = new MySqlConnection(ConnString);
                await conn.OpenAsync();
                await using var cmd = conn.CreateCommand();
                // Column name is hardcoded (whitelist) so SQL injection is impossible
                cmd.CommandText = $"UPDATE wp_player_skins SET {column} = @val WHERE steamid=@sid AND weapon_team=@team AND weapon_defindex=@def";
                cmd.Parameters.AddWithValue("@val", value);
                cmd.Parameters.AddWithValue("@sid", steamId);
                cmd.Parameters.AddWithValue("@team", team);
                cmd.Parameters.AddWithValue("@def", (int)defindex);
                int rows = await cmd.ExecuteNonQueryAsync();
                reply = rows > 0
                    ? $" \x06[Seed]\x01 {userVisible} on defindex=\x06{defindex}\x01."
                    : $" \x07[Seed]\x01 No DB row for team={team} defindex={defindex}.";
            }
            catch (Exception ex) { reply = $" \x07[Seed]\x01 SQL: {ex.Message}"; }

            Server.NextFrame(() =>
            {
                var p = Utilities.GetPlayerFromSlot(slot);
                if (p == null || !p.IsValid) return;
                p.PrintToChat(reply);
                TriggerWpRefresh(p);
            });
        });
    }

    private static (CBasePlayerWeapon?, string) GetHeldWeapon(CCSPlayerController player)
    {
        var pawn = player.PlayerPawn.Value;
        var active = pawn?.WeaponServices?.ActiveWeapon.Value;
        if (active == null || !active.IsValid) return (null, "");
        return (active, active.DesignerName);
    }

    private string GetWeaponClassname(int slot)
    {
        var p = Utilities.GetPlayerFromSlot(slot);
        if (p == null || !p.IsValid) return "";
        var (_, cn) = GetHeldWeapon(p);
        return cn;
    }

    // ============================================================
    // MenuManager helper — reflection bypasses obsolete-as-error
    // ============================================================
    // "by Mavi" credit label rendered in epic-purple, styled as a footer-like divider
    // so it doesn't look selectable. Added as the last menu option since MenuManager
    // doesn't have a native footer/subtitle slot below the W/S/E/R nav hints.
    private const string CreditOption = "── <font color='#A335EE'>by Mavi</font> ──";

    // Appends the credit as a no-op final option on every menu we create.
    private void AppendCreditOption(dynamic menu)
    {
        try
        {
            Action<CCSPlayerController, object> noop = (c, o) => { /* credit label — no action */ };
            menu.AddMenuOption(CreditOption, noop);
        }
        catch { }
    }

    private object? CreateMenu(string title)
    {
        if (_menuApi == null) return null;
        try
        {
            var best = _menuApi.GetType().GetMethods()
                .Where(m => m.Name == "NewMenuForcetype")
                .OrderBy(m => m.GetParameters().Count(pp => !pp.IsOptional))
                .FirstOrDefault();
            if (best == null) return null;
            var parameters = best.GetParameters();
            object?[] args = new object[parameters.Length];
            args[0] = title;
            // ButtonMenu = scrollable center-screen menu with WASD navigation
            args[1] = MenuType.ButtonMenu;
            for (int i = 2; i < parameters.Length; i++)
                args[i] = parameters[i].IsOptional ? Type.Missing : null;
            return best.Invoke(_menuApi, args);
        }
        catch { return null; }
    }
